Example snippet to include in docs: 

// create a session with 1s min drain
ctx := context.Background()
sess, err := stream.NewStreamSession(ctx, stream.WithMinDrain(1*time.Second), stream.EnableResume(true))
if err != nil { log.Fatal(err) }
// read loop
go func() {
  for msg := range sess.Messages() {
    process(msg)
  }
  log.Println("session finished")
}()
// graceful shutdown on SIGINT
ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)
defer stop()
<-ctx.Done()
if err := sess.CloseGracefully(context.Background(), 2*time.Second); err != nil {
  sess.Abort()
}
